<?php
if(!defined('ABSPATH'))exit;
function legacyx_client360_menu(){add_submenu_page(null,'Client 360','Client 360','manage_options','legacyx-client-360','legacyx_render_client360');}add_action('admin_menu','legacyx_client360_menu');
function legacyx_client360_value($client_id,$key,$fallback='—'){$v=get_post_meta($client_id,'_legacyx_'.$key,true);return $v!==''?$v:$fallback;}
function legacyx_client360_render_list($items,$type){if(!$items){echo '<p class="l360-empty">No records yet.</p>';return;}echo '<div class="l360-list">';foreach($items as $item){$edit=get_edit_post_link($item->ID);echo '<a href="'.esc_url($edit).'" class="l360-row"><div><strong>'.esc_html(get_the_title($item)).'</strong>';$meta='';if($type==='application'){$meta=legacyx_client360_value($item->ID,'status','Pending').' · '.legacyx_client360_value($item->ID,'type','Application');}elseif($type==='workflow'){$meta=legacyx_client360_value($item->ID,'work_status','Open').' · '.legacyx_client360_value($item->ID,'work_type','Task');}elseif($type==='billing'){$meta=legacyx_billing_effective_status($item->ID).' · '.legacyx_money(legacyx_client360_value($item->ID,'amount_due','0'));}echo '<small>'.esc_html($meta).'</small></div><span>Open →</span></a>';}echo '</div>';}
function legacyx_render_client360(){if(!current_user_can('manage_options'))return;$client_id=absint($_GET['client_id']??0);$client=$client_id?get_post($client_id):null;if(!$client||$client->post_type!=='legacyx_client'){echo '<div class="wrap"><h1>Client 360</h1><p>Select a valid Universal Client Profile from Firm OS.</p><p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=legacyx-firm-os')).'">Return to Firm OS</a></p></div>';return;}$credit=legacyx_creditos_get_client_data($client_id);$biz=legacyx_business_get_client_data($client_id);$workflow=legacyx_get_client_workflow($client_id);$apps=legacyx_get_client_applications($client_id);$billing=legacyx_get_client_billing($client_id);$wcounts=legacyx_workflow_counts($client_id);$acounts=legacyx_application_counts($client_id);$bcounts=legacyx_billing_counts($client_id);$wp_user_id=absint(get_post_meta($client_id,'_legacyx_wp_user_id',true));$wp_user=$wp_user_id?get_userdata($wp_user_id):null;$client_code=legacyx_client360_value($client_id,'client_id','—');$status=legacyx_client360_value($client_id,'status','—');$service=legacyx_client360_value($client_id,'service_level','—');$business=legacyx_client360_value($client_id,'business_name','—');$capital=legacyx_client360_value($client_id,'capital_goal','—');$email=legacyx_client360_value($client_id,'email','—');$phone=legacyx_client360_value($client_id,'phone','—');?>
<div class="wrap l360"><div class="l360-top"><div><a href="<?php echo esc_url(admin_url('admin.php?page=legacyx-firm-os'));?>">← Firm OS</a><span>LEGACY X FIRM OS · CLIENT 360</span><h1><?php echo esc_html($client->post_title);?></h1><p><?php echo esc_html($client_code.' · '.$business);?></p></div><div class="l360-actions"><a class="button" href="<?php echo esc_url(get_edit_post_link($client_id));?>">Edit Universal Profile</a><?php if($wp_user):?><a class="button button-primary" href="<?php echo esc_url(home_url('/client-portal/'));?>" target="_blank" rel="noopener">Open Client OS ↗</a><?php endif;?></div></div>
<div class="l360-metrics"><div><span>Relationship</span><strong><?php echo esc_html($status);?></strong></div><div><span>Service Level</span><strong><?php echo esc_html($service);?></strong></div><div><span>Applications</span><strong><?php echo esc_html($acounts['total']);?></strong><small><?php echo esc_html($acounts['active']);?> active</small></div><div><span>Workflow</span><strong><?php echo esc_html($wcounts['open']);?></strong><small>open items</small></div><div><span>Billing Balance</span><strong><?php echo esc_html(legacyx_money($bcounts['balance']));?></strong><small><?php echo esc_html($bcounts['open']);?> open</small></div><div><span>Capital Goal</span><strong><?php echo esc_html($capital);?></strong></div></div>
<div class="l360-grid"><section><div class="l360-head"><span>RELATIONSHIP</span><h2>Client Profile</h2></div><dl><div><dt>Client ID</dt><dd><?php echo esc_html($client_code);?></dd></div><div><dt>Business</dt><dd><?php echo esc_html($business);?></dd></div><div><dt>Email</dt><dd><?php echo esc_html($email);?></dd></div><div><dt>Phone</dt><dd><?php echo esc_html($phone);?></dd></div><div><dt>Portal Account</dt><dd><?php echo esc_html($wp_user?$wp_user->user_login:'Not linked');?></dd></div><div><dt>Relationship Owner</dt><dd><?php echo esc_html(legacyx_client360_value($client_id,'relationship_owner','—'));?></dd></div></dl></section>
<section><div class="l360-head"><span>CREDITOS</span><h2>Credit & Capital</h2></div><dl><div><dt>Personal Stage</dt><dd><?php echo esc_html($credit['personal_stage']);?></dd></div><div><dt>Business Stage</dt><dd><?php echo esc_html($credit['business_stage']);?></dd></div><div><dt>Personal Score / Range</dt><dd><?php echo esc_html($credit['personal_score']?:'—');?></dd></div><div><dt>Business Credit</dt><dd><?php echo esc_html($credit['business_status']);?></dd></div><div><dt>Funding Goal</dt><dd><?php echo esc_html($credit['funding_goal']?:'—');?></dd></div><div class="wide"><dt>Next Action</dt><dd><?php echo esc_html($credit['next_action']);?></dd></div></dl></section>
<section><div class="l360-head"><span>BUSINESS CENTER</span><h2>Enterprise Readiness</h2></div><dl><div><dt>Entity</dt><dd><?php echo esc_html($biz['entity_type']?:'—');?></dd></div><div><dt>Formation</dt><dd><?php echo esc_html($biz['formation_status']);?></dd></div><div><dt>Banking</dt><dd><?php echo esc_html($biz['banking_status']);?></dd></div><div><dt>Compliance</dt><dd><?php echo esc_html($biz['compliance_status']);?></dd></div><div><dt>Operations</dt><dd><?php echo esc_html($biz['operations_stage']);?></dd></div><div class="wide"><dt>Strategic Goal</dt><dd><?php echo esc_html($biz['strategic_goal']?:'—');?></dd></div><div class="wide"><dt>Next Action</dt><dd><?php echo esc_html($biz['next_action']);?></dd></div></dl></section>
<section><div class="l360-head"><span>EXECUTIVE NEXT ACTION</span><h2>Relationship Focus</h2></div><div class="l360-focus"><p><strong>CreditOS:</strong> <?php echo esc_html($credit['next_action']);?></p><p><strong>Business:</strong> <?php echo esc_html($biz['next_action']);?></p><?php if($bcounts['balance']>0):?><p><strong>Billing:</strong> <?php echo esc_html(legacyx_money($bcounts['balance']));?> outstanding across current billing records.</p><?php endif;?><?php if($acounts['active']>0):?><p><strong>Applications:</strong> <?php echo esc_html($acounts['active']);?> active application<?php echo $acounts['active']===1?'':'s';?> require ongoing tracking.</p><?php endif;?></div></section></div>
<div class="l360-record-grid"><section><div class="l360-head"><span>APPLICATIONS</span><h2>Application Pipeline</h2></div><?php legacyx_client360_render_list(array_slice($apps,0,5),'application');?></section><section><div class="l360-head"><span>WORKFLOW</span><h2>Documents & Tasks</h2></div><?php legacyx_client360_render_list(array_slice($workflow,0,5),'workflow');?></section><section><div class="l360-head"><span>BILLING</span><h2>Invoices & Payments</h2></div><?php legacyx_client360_render_list(array_slice($billing,0,5),'billing');?></section></div></div><?php }
function legacyx_client360_styles($hook){if($hook!=='admin_page_legacyx-client-360')return;wp_register_style('legacyx-client360',false);wp_enqueue_style('legacyx-client360');$css='.l360{max-width:1440px;margin:24px 24px 60px 4px;color:#171512}.l360-top{background:#171512;color:#fff;padding:32px 36px;display:flex;justify-content:space-between;align-items:end}.l360-top a{color:#fff}.l360-top span,.l360-head span{display:block;color:#f05a16;font-size:11px;font-weight:800;letter-spacing:.15em;margin-top:10px}.l360-top h1{font-family:Georgia,serif;font-size:38px;margin:7px 0}.l360-top p{color:#c9c3ba}.l360-actions{display:flex;gap:8px}.l360-metrics{display:grid;grid-template-columns:repeat(6,1fr);background:#fff;border:1px solid #ded8ce;margin-top:18px}.l360-metrics>div{padding:20px;border-right:1px solid #ded8ce}.l360-metrics>div:last-child{border-right:0}.l360-metrics span,.l360-metrics small{display:block;color:#746e65}.l360-metrics strong{font-family:Georgia,serif;font-size:24px;display:block;margin:6px 0}.l360-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.l360-grid section,.l360-record-grid section{background:#fff;border:1px solid #ded8ce;padding:26px}.l360-head h2{font-family:Georgia,serif;font-size:27px;margin:4px 0 18px}.l360 dl{display:grid;grid-template-columns:1fr 1fr;gap:0;margin:0}.l360 dl>div{padding:12px 0;border-bottom:1px solid #ece7df}.l360 dl .wide{grid-column:1/-1}.l360 dt{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#746e65}.l360 dd{margin:5px 0 0;font-weight:700}.l360-focus p{padding:12px 0;border-bottom:1px solid #ece7df;margin:0}.l360-record-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}.l360-row{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:13px 0;border-bottom:1px solid #ece7df;color:#171512;text-decoration:none}.l360-row small{display:block;color:#746e65;margin-top:4px}.l360-row span{color:#f05a16;font-weight:700}.l360-empty{color:#746e65}@media(max-width:1100px){.l360-metrics{grid-template-columns:repeat(3,1fr)}.l360-record-grid{grid-template-columns:1fr}}@media(max-width:760px){.l360-top{display:block}.l360-actions{margin-top:15px;flex-wrap:wrap}.l360-metrics,.l360-grid{grid-template-columns:1fr}.l360-metrics>div{border-right:0;border-bottom:1px solid #ded8ce}.l360 dl{grid-template-columns:1fr}}';wp_add_inline_style('legacyx-client360',$css);}add_action('admin_enqueue_scripts','legacyx_client360_styles');
